const row = items[0].json;
const seconds = row.seconds_since_last_archive === null || row.seconds_since_last_archive === undefined
  ? null
  : Number(row.seconds_since_last_archive);
const neverArchived = seconds === null || Number.isNaN(seconds);
const stale = neverArchived || seconds > 86400;
const lastFailed = row.last_failed_time ? new Date(row.last_failed_time).getTime() : 0;
const lastArchived = row.last_archived_time ? new Date(row.last_archived_time).getTime() : 0;
const failedAfterSuccess = lastFailed > 0 && lastFailed > lastArchived;
const unhealthy = stale || failedAfterSuccess;

const age = neverArchived ? 'never' : Math.round(seconds / 60) + ' minutes ago';
const lines = [
  (unhealthy ? '*STALE*' : '*OK*') + ' Postgres archive check for `' + row.database_name + '`',
  'Last archived: ' + (row.last_archived_time || 'never') + ' (' + age + ')',
  'Last failure: ' + (row.last_failed_time || 'none'),
  'Archived count: ' + row.archived_count + ', failed count: ' + row.failed_count,
  'Database size: ' + row.database_size,
  'In recovery: ' + row.in_recovery,
  'Checked: ' + row.checked_at,
];

return [{ json: { text: lines.join('\n'), unhealthy } }];
